node -e "
const path = require('path');
const fs = require('fs');
const projectRoot = '/mnt/d/openClass/openClasses/domains/game-engine/godotProjects/slayDemo/client/slay-demo';

const dataFiles = ['cards','relics','potions','enemies','encounters'];
const counts = {};
dataFiles.forEach(f => {
  try {
    const d = JSON.parse(fs.readFileSync(path.join(projectRoot, 'data', f + '.json'), 'utf8'));
    counts[f] = d[f] ? d[f].length : '?';
  } catch(e) { counts[f] = 'err'; }
});

const scriptCount = fs.readdirSync(path.join(projectRoot,'scripts'), {recursive:true}).filter(f=>f.endsWith('.gd')).length;
const testCount = fs.readdirSync(path.join(projectRoot,'tests'), {recursive:true}).filter(f=>f.endsWith('.gd')).length;

const { execSync } = require('child_process');
const lastCommit = execSync('git -C /mnt/d/openClass/openClasses/domains/game-engine/godotProjects/slayDemo log --oneline -1').toString().trim();
const commitCount = execSync('git -C /mnt/d/openClass/openClasses/domains/game-engine/godotProjects/slayDemo rev-list --count main').toString().trim();

console.log('=== slayDemo 提交后状态快照 ===');
console.log('最新提交: ' + lastCommit);
console.log('总提交数: ' + commitCount);
console.log('');
console.log('数据规模:');
dataFiles.forEach(f => console.log('  ' + f + ': ' + counts[f]));
console.log('');
console.log('代码规模:');
console.log('  scripts: ' + scriptCount + ' .gd 文件');
console.log('  tests:   ' + testCount + ' .gd 文件');
console.log('');
console.log('请根据以上快照，分析本次提交完成了什么，并规划下一步推进计划。');
"
